<script setup lang="ts">
import { onMounted, ref, watch } from "vue";
import { ArrowLeft, BookOpen, FileText, GraduationCap, Pencil, Plus, Trash2, X } from "@lucide/vue";
import { api, formatDate, formatEnum, type AdminBookDetail, type AdminEdition, type BookCopy, type DigitalFile } from "../../api";
import ConfirmDialog from "../../components/ConfirmDialog.vue";
import { notify } from "../../toast";

const props = defineProps<{ id: string }>();
const emit = defineEmits<{ navigate: [path: string] }>();
const book = ref<AdminBookDetail | null>(null); const loading = ref(true); const error = ref(""); const saving = ref(false); const formError = ref("");
const modal = ref<"edition" | "digital" | "copy" | null>(null); const currentEdition = ref<AdminEdition | null>(null); const currentDigital = ref<DigitalFile | null>(null); const currentCopy = ref<BookCopy | null>(null);
const editionForm = ref({ isbn: "", publisher: "", edition_number: "", publication_year: "", page_count: "", language: "" });
const digitalForm = ref<{ file: File | null; access_level: "PUBLIC" | "REGISTERED" | "MEMBER"; allow_download: boolean }>({ file: null, access_level: "REGISTERED", allow_download: false });
const copyForm = ref({ barcode: "", shelf_location: "", condition: "", acquired_at: "" });
const deleting = ref<{ title: string; message: string; path: string } | null>(null); const deleteBusy = ref(false);

async function load() { loading.value = true; error.value = ""; try { book.value = await api<AdminBookDetail>(`/api/v1/admin/books/${props.id}`); } catch (caught) { error.value = caught instanceof Error ? caught.message : "Unable to load book."; } finally { loading.value = false; } }
function openEdition(edition?: AdminEdition) { currentEdition.value = edition || null; editionForm.value = { isbn: edition?.isbn || "", publisher: edition?.publisher || "", edition_number: edition?.edition_number || "", publication_year: edition?.publication_year?.toString() || "", page_count: edition?.page_count?.toString() || "", language: edition?.language || "" }; formError.value = ""; modal.value = "edition"; }
function openDigital(edition: AdminEdition, file?: DigitalFile) { currentEdition.value = edition; currentDigital.value = file || null; digitalForm.value = { file: null, access_level: file?.access_level || "REGISTERED", allow_download: file?.allow_download || false }; formError.value = ""; modal.value = "digital"; }
function pickPdf(event: Event) { digitalForm.value.file = (event.target as HTMLInputElement).files?.[0] || null; }
function localDate(value: string | null) { return value ? value.slice(0, 16) : ""; }
function openCopy(edition: AdminEdition, copy?: BookCopy) { currentEdition.value = edition; currentCopy.value = copy || null; copyForm.value = { barcode: copy?.barcode || "", shelf_location: copy?.shelf_location || "", condition: copy?.condition || "", acquired_at: localDate(copy?.acquired_at || null) }; formError.value = ""; modal.value = "copy"; }
function nullable(value: string) { return value.trim() || null; }
async function saveEdition() { saving.value = true; formError.value = ""; const payload = { isbn: nullable(editionForm.value.isbn), publisher: nullable(editionForm.value.publisher), edition_number: nullable(editionForm.value.edition_number), publication_year: editionForm.value.publication_year ? Number(editionForm.value.publication_year) : null, page_count: editionForm.value.page_count ? Number(editionForm.value.page_count) : null, language: nullable(editionForm.value.language) }; try { if (currentEdition.value) await api(`/api/v1/admin/editions/${currentEdition.value.id}`, { method: "PATCH", body: JSON.stringify(payload) }); else await api(`/api/v1/admin/books/${props.id}/editions`, { method: "POST", body: JSON.stringify(payload) }); notify(currentEdition.value ? "Edition updated" : "Edition added"); modal.value = null; load(); } catch (caught) { formError.value = caught instanceof Error ? caught.message : "Unable to save edition."; } finally { saving.value = false; } }
async function saveDigital() { if (!currentEdition.value) return; saving.value = true; formError.value = ""; try { if (currentDigital.value) { if (digitalForm.value.file) { const replacement = new FormData(); replacement.append("file", digitalForm.value.file); await api(`/api/v1/admin/digital-files/${currentDigital.value.id}/replace`, { method: "POST", body: replacement }); } await api(`/api/v1/admin/digital-files/${currentDigital.value.id}`, { method: "PATCH", body: JSON.stringify({ access_level: digitalForm.value.access_level, allow_download: digitalForm.value.allow_download }) }); } else { if (!digitalForm.value.file) throw new Error("Choose a PDF file."); const upload = new FormData(); upload.append("file", digitalForm.value.file); upload.append("access_level", digitalForm.value.access_level); upload.append("allow_download", String(digitalForm.value.allow_download)); await api(`/api/v1/admin/editions/${currentEdition.value.id}/digital-files`, { method: "POST", body: upload }); } notify(currentDigital.value ? "Digital edition updated" : "PDF uploaded and processed"); modal.value = null; load(); } catch (caught) { formError.value = caught instanceof Error ? caught.message : "Unable to save digital edition."; } finally { saving.value = false; } }
async function retryProcessing(file: DigitalFile) { try { await api(`/api/v1/admin/digital-files/${file.id}/process`, { method: "POST" }); notify("PDF processing completed."); load(); } catch (caught) { notify(caught instanceof Error ? caught.message : "Unable to process PDF.", "error"); } }
async function saveCopy() { if (!currentEdition.value) return; saving.value = true; formError.value = ""; const payload = { barcode: copyForm.value.barcode, shelf_location: nullable(copyForm.value.shelf_location), condition: nullable(copyForm.value.condition), acquired_at: copyForm.value.acquired_at ? new Date(copyForm.value.acquired_at).toISOString() : null, ...(!currentCopy.value ? { status: "AVAILABLE" } : {}) }; try { if (currentCopy.value) await api(`/api/v1/admin/book-copies/${currentCopy.value.id}`, { method: "PATCH", body: JSON.stringify(payload) }); else await api(`/api/v1/admin/editions/${currentEdition.value.id}/copies`, { method: "POST", body: JSON.stringify(payload) }); notify(currentCopy.value ? "Copy details updated" : "Physical copy added"); modal.value = null; load(); } catch (caught) { formError.value = caught instanceof Error ? caught.message : "Unable to save copy."; } finally { saving.value = false; } }
async function confirmDelete() { if (!deleting.value) return; deleteBusy.value = true; try { await api(deleting.value.path, { method: "DELETE" }); notify(`${deleting.value.title} deleted`); deleting.value = null; load(); } catch (caught) { notify(caught instanceof Error ? caught.message : "Unable to delete resource.", "error"); } finally { deleteBusy.value = false; } }
watch(() => props.id, load); onMounted(load);
</script>
<template>
  <main class="admin-detail">
    <button class="back-link" type="button" @click="emit('navigate', '/admin/books')"><ArrowLeft :size="17" />Books</button>
    <div v-if="loading" class="detail-loading"><span></span><span></span><span></span></div>
    <section v-else-if="error" class="detail-error"><h1>Book unavailable</h1><p>{{ error }}</p><button type="button" @click="load">Try again</button></section>
    <template v-else-if="book">
      <header class="detail-heading"><div><p class="eyebrow">Catalog management</p><h1>{{ book.title }}</h1><p>{{ book.authors.map((author) => author.name).join(', ') }}</p></div><div><em :class="book.status.toLowerCase()">{{ book.status }}</em><button type="button" @click="emit('navigate', `/admin/books?edit=${book.id}`)"><Pencil :size="16" />Edit book</button></div></header>
      <section class="book-overview"><div class="admin-cover"><img v-if="book.cover_url" :src="book.cover_url" :alt="`${book.title} cover`" /><BookOpen v-else :size="35" /></div><dl><div><dt>Category</dt><dd>{{ book.category.name }}</dd></div><div><dt>Type</dt><dd>{{ formatEnum(book.book_type) }}</dd></div><div><dt>Language</dt><dd>{{ book.language.toUpperCase() }}</dd></div><div><dt>Slug</dt><dd>{{ book.slug }}</dd></div><div v-if="book.description"><dt>Description</dt><dd>{{ book.description }}</dd></div></dl></section>
      <section class="editions-section"><header><div><p class="eyebrow">Editions</p><h2>Formats and copies</h2></div><button type="button" @click="openEdition()"><Plus :size="17" />Add edition</button></header><div v-if="!book.editions.length" class="resource-empty">This book has no editions yet.</div><article v-for="(edition, editionIndex) in book.editions" :key="edition.id" class="edition-block"><header><div><span>Edition {{ editionIndex + 1 }}</span><h3>{{ edition.edition_number || edition.publisher || 'Untitled edition' }}</h3><p>{{ [edition.publication_year, edition.publisher, edition.language?.toUpperCase()].filter(Boolean).join(' / ') || 'No publication details' }}</p></div><div><button type="button" aria-label="Edit edition" @click="openEdition(edition)"><Pencil :size="17" /></button><button type="button" aria-label="Delete edition" @click="deleting = { title: 'Edition', message: 'This only succeeds when the edition has no digital files or physical copies.', path: `/api/v1/admin/editions/${edition.id}` }"><Trash2 :size="17" /></button></div></header>
        <div class="resource-columns"><section><div class="resource-title"><div><FileText :size="18" /><h4>Digital edition</h4></div><span><button v-if="book.book_type !== 'FICTION' && edition.digital_files.some(file => file.processing_status === 'READY')" type="button" @click="emit('navigate', `/admin/books/${book.id}/learning/${edition.id}`)"><GraduationCap :size="16" />Learning</button><button v-if="!edition.digital_files.length" type="button" @click="openDigital(edition)"><Plus :size="16" />Upload PDF</button></span></div><div v-if="!edition.digital_files.length" class="mini-empty">No PDF uploaded.</div><div v-for="file in edition.digital_files" :key="file.id" class="resource-row"><div><strong>{{ file.original_filename || 'Legacy digital file' }}</strong><small>{{ file.access_level }} / {{ formatEnum(file.processing_status) }} / {{ file.file_size ? `${file.file_size.toLocaleString()} bytes` : 'Unknown size' }}</small><small v-if="file.processing_error" class="file-error">{{ file.processing_error }}</small></div><span><button v-if="file.processing_status === 'FAILED'" type="button" aria-label="Retry processing" title="Retry processing" @click="retryProcessing(file)"><FileText :size="15" /></button><button type="button" aria-label="Edit digital edition" @click="openDigital(edition, file)"><Pencil :size="15" /></button><button type="button" aria-label="Delete digital edition" @click="deleting = { title: 'Digital edition', message: 'The stored PDF will be permanently removed. Reader data must be cleared first.', path: `/api/v1/admin/digital-files/${file.id}` }"><Trash2 :size="15" /></button></span></div></section>
          <section><div class="resource-title"><div><BookOpen :size="18" /><h4>Physical copies</h4></div><button type="button" @click="openCopy(edition)"><Plus :size="16" />Add</button></div><div v-if="!edition.physical_copies.length" class="mini-empty">No physical copies.</div><div v-for="copy in edition.physical_copies" :key="copy.id" class="resource-row"><div><strong>{{ copy.barcode }}</strong><small>{{ copy.shelf_location || 'Shelf not set' }} / <em :class="copy.status.toLowerCase()">{{ copy.status }}</em></small></div><span><button type="button" aria-label="Edit copy" @click="openCopy(edition, copy)"><Pencil :size="15" /></button><button v-if="copy.status === 'AVAILABLE'" type="button" aria-label="Delete copy" @click="deleting = { title: `Copy ${copy.barcode}`, message: 'Delete this available physical copy record?', path: `/api/v1/admin/book-copies/${copy.id}` }"><Trash2 :size="15" /></button></span></div></section></div>
      </article></section>
    </template>

    <Teleport to="body"><div v-if="modal" class="form-backdrop" @click.self="modal = null"><section class="resource-form" role="dialog" aria-modal="true"><header><h2>{{ modal === 'edition' ? (currentEdition ? 'Edit edition' : 'Add edition') : modal === 'digital' ? (currentDigital ? 'Edit digital edition' : 'Upload PDF') : (currentCopy ? 'Edit physical copy' : 'Add physical copy') }}</h2><button type="button" aria-label="Close" @click="modal = null"><X :size="20" /></button></header><form v-if="modal === 'edition'" @submit.prevent="saveEdition"><label>ISBN<input v-model="editionForm.isbn" maxlength="32" /></label><label>Publisher<input v-model="editionForm.publisher" maxlength="255" /></label><label>Edition number<input v-model="editionForm.edition_number" maxlength="50" /></label><label>Publication year<input v-model="editionForm.publication_year" type="number" min="1" /></label><label>Page count<input v-model="editionForm.page_count" type="number" min="1" /></label><label>Language<input v-model="editionForm.language" maxlength="50" /></label><p v-if="formError" class="form-error">{{ formError }}</p><footer><button type="button" @click="modal = null">Cancel</button><button type="submit" :disabled="saving">{{ saving ? 'Saving...' : 'Save edition' }}</button></footer></form><form v-else-if="modal === 'digital'" @submit.prevent="saveDigital"><label class="wide">{{ currentDigital ? 'Replacement PDF (optional)' : 'PDF file' }}<input type="file" accept="application/pdf,.pdf" :required="!currentDigital" @change="pickPdf" /></label><fieldset class="wide"><legend>Access level</legend><label><input v-model="digitalForm.access_level" type="radio" value="PUBLIC" /><span><strong>Public</strong><small>Anyone can access</small></span></label><label><input v-model="digitalForm.access_level" type="radio" value="REGISTERED" /><span><strong>Registered</strong><small>Requires a Litera account</small></span></label><label><input v-model="digitalForm.access_level" type="radio" value="MEMBER" /><span><strong>Member</strong><small>Requires active membership</small></span></label></fieldset><label class="wide download-toggle"><input v-model="digitalForm.allow_download" type="checkbox" /><span><strong>Allow PDF download</strong><small>Reading in the browser remains available when disabled.</small></span></label><p v-if="currentDigital" class="copy-status wide">Selecting a new PDF replaces the current document. Replacement is blocked when readers have saved progress or bookmarks.</p><p v-if="formError" class="form-error wide">{{ formError }}</p><footer class="wide"><button type="button" @click="modal = null">Cancel</button><button type="submit" :disabled="saving">{{ saving ? 'Processing...' : currentDigital ? 'Save changes' : 'Upload PDF' }}</button></footer></form><form v-else @submit.prevent="saveCopy"><label>Barcode<input v-model="copyForm.barcode" required maxlength="255" /></label><label>Shelf location<input v-model="copyForm.shelf_location" maxlength="255" /></label><label>Condition<input v-model="copyForm.condition" maxlength="255" /></label><label>Acquired<input v-model="copyForm.acquired_at" type="datetime-local" /></label><p v-if="currentCopy" class="copy-status wide">Status: <strong>{{ currentCopy.status }}</strong>. Borrowing statuses are controlled by the circulation workflow.</p><p v-if="formError" class="form-error wide">{{ formError }}</p><footer class="wide"><button type="button" @click="modal = null">Cancel</button><button type="submit" :disabled="saving">{{ saving ? 'Saving...' : 'Save copy' }}</button></footer></form></section></div></Teleport>
    <ConfirmDialog :open="Boolean(deleting)" :title="`Delete ${deleting?.title || ''}?`" :message="deleting?.message || ''" confirm-label="Delete" destructive :busy="deleteBusy" @cancel="deleting = null" @confirm="confirmDelete" />
  </main>
</template>
<style scoped>
.admin-detail { padding: 52px clamp(28px, 5vw, 75px) 110px; }.back-link { display: inline-flex; align-items: center; gap: 8px; padding: 7px 0; background: transparent; color: #69716b; }.detail-heading { display: flex; justify-content: space-between; gap: 35px; align-items: end; padding: 45px 0 55px; }.detail-heading h1 { max-width: 760px; margin: 0; overflow-wrap: anywhere; font-size: clamp(2.8rem, 5vw, 5rem); font-weight: 560; line-height: 1; }.detail-heading p:not(.eyebrow) { color: #69716b; }.detail-heading > div:last-child { display: flex; align-items: center; gap: 12px; }.detail-heading em, .resource-row em { padding: 5px 8px; background: #e1e5e1; font-size: .63rem; font-style: normal; }.detail-heading em.published, .resource-row em.available { background: #d8e8df; color: #315a46; }.detail-heading button { display: flex; align-items: center; gap: 8px; min-height: 40px; padding: 0 13px; border: 1px solid #b9c0ba; background: transparent; }.book-overview { display: grid; grid-template-columns: 150px 1fr; gap: 55px; padding: 40px; background: #dce8e3; }.admin-cover { display: grid; aspect-ratio: 2/3; overflow: hidden; place-items: center; background: #c8d8d0; }.admin-cover img { width: 100%; height: 100%; object-fit: cover; }.book-overview dl { display: grid; grid-template-columns: repeat(2, 1fr); gap: 0 45px; margin: 0; }.book-overview dl div { display: flex; justify-content: space-between; gap: 15px; padding: 15px 0; border-bottom: 1px solid #aebfb6; }.book-overview dl div:last-child { grid-column: 1/-1; }.book-overview dt { color: #69766f; font-size: .75rem; }.book-overview dd { margin: 0; text-align: right; }.editions-section { margin-top: 90px; }.editions-section > header { display: flex; justify-content: space-between; align-items: end; margin-bottom: 30px; }.editions-section h2 { margin: 0; font-size: 2.4rem; font-weight: 560; }.editions-section > header button, .resource-title > button { display: flex; align-items: center; gap: 7px; min-height: 40px; padding: 0 13px; border: 1px solid #173d32; background: #173d32; color: white; }.edition-block { margin-bottom: 28px; border: 1px solid #ccd1cc; background: #f8f9f6; }.edition-block > header { display: flex; justify-content: space-between; gap: 20px; padding: 25px; border-bottom: 1px solid #ccd1cc; }.edition-block h3 { margin: 5px 0; font-size: 1.3rem; }.edition-block header span, .edition-block header p { color: #747b75; font-size: .7rem; }.edition-block header p { margin: 0; }.edition-block header > div:last-child { display: flex; }.edition-block header button, .resource-row button { display: grid; width: 35px; height: 35px; place-items: center; background: transparent; }.resource-columns { display: grid; grid-template-columns: 1fr 1fr; }.resource-columns > section { min-width: 0; padding: 24px; }.resource-columns > section + section { border-left: 1px solid #ccd1cc; }.resource-title { display: flex; justify-content: space-between; align-items: center; margin-bottom: 16px; }.resource-title > div { display: flex; align-items: center; gap: 9px; }.resource-title h4 { margin: 0; }.resource-title > button { min-height: 33px; padding: 0 10px; background: transparent; color: #173d32; }.resource-row { display: flex; justify-content: space-between; gap: 12px; align-items: center; padding: 13px 0; border-top: 1px solid #d9ddd9; }.resource-row > div { display: grid; min-width: 0; gap: 5px; }.resource-row strong, .resource-row small { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }.resource-row small { color: #747b75; }.resource-row > span { display: flex; }.resource-empty, .mini-empty { padding: 35px 0; border-block: 1px solid #d3d8d3; color: #747b75; }.mini-empty { padding: 18px 0; font-size: .8rem; }.detail-error { padding: 100px 0; }.detail-error h1 { font-size: 3rem; }.detail-loading { display: grid; gap: 15px; padding-top: 60px; }.detail-loading span { height: 90px; background: #e1e4e0; }
.form-backdrop { position: fixed; z-index: 70; inset: 0; display: grid; padding: 20px; place-items: center; background: rgba(20,26,22,.48); }.resource-form { width: min(620px, 100%); max-height: calc(100vh - 40px); overflow-y: auto; padding: 30px; background: #f7f8f5; }.resource-form > header { display: flex; justify-content: space-between; margin-bottom: 25px; }.resource-form h2 { margin: 0; }.resource-form header button { padding: 4px; background: transparent; }.resource-form form { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }.resource-form label { display: grid; gap: 7px; color: #545c56; font-size: .75rem; font-weight: 650; }.resource-form input, .resource-form select { width: 100%; min-height: 42px; padding: 7px 9px; border: 1px solid #bac1bb; background: white; }.resource-form .wide { grid-column: 1/-1; }.resource-form fieldset { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; border: 1px solid #bac1bb; }.resource-form fieldset label { display: flex; align-items: start; gap: 8px; padding: 8px; }.resource-form fieldset input { width: 15px; min-height: 15px; }.resource-form fieldset span { display: grid; gap: 4px; }.resource-form fieldset small { color: #7d847e; font-weight: 400; }.resource-form .download-toggle { display: flex; grid-template-columns: 18px 1fr; align-items: start; }.resource-form .download-toggle input { width: 16px; min-height: 16px; }.resource-form .download-toggle span { display: grid; gap: 4px; }.resource-form .download-toggle small { color: #7d847e; font-weight: 400; }.resource-form footer { display: flex; justify-content: flex-end; gap: 9px; }.resource-form footer button { min-height: 42px; padding: 0 15px; border: 1px solid #b5bcb6; background: transparent; }.resource-form footer button:last-child { background: #173d32; color: white; }.form-error,.file-error { margin: 0; color: #a14539 !important; }.copy-status { margin: 0; padding: 12px; background: #e7eae7; color: #626a64; font-size: .78rem; }
.resource-title > span { display: flex; gap: 7px; }.resource-title > span button { display: flex; align-items: center; gap: 6px; min-height: 33px; padding: 0 9px; border: 1px solid #173d32; background: transparent; color: #173d32; }
@media (max-width: 800px) { .admin-detail { padding: 75px 22px; }.detail-heading { display: block; }.detail-heading > div:last-child { margin-top: 24px; }.book-overview { grid-template-columns: 100px 1fr; gap: 25px; padding: 25px; }.book-overview dl { grid-template-columns: 1fr; }.book-overview dl div:last-child { grid-column: auto; }.resource-columns { grid-template-columns: 1fr; }.resource-columns > section + section { border-top: 1px solid #ccd1cc; border-left: 0; } }
@media (max-width: 520px) { .book-overview { grid-template-columns: 1fr; }.admin-cover { width: 120px; }.resource-form form { grid-template-columns: 1fr; }.resource-form .wide { grid-column: auto; }.resource-form fieldset { grid-template-columns: 1fr; } }
</style>
